#BachFugueInGminorArrLisztBWV542-RF.rb
#coded for sonic pi by Robin NEwman, October 2019
#there are two ;pl functions pl and plx
#one plays :piano synth, the other midi.
#current active one is named pl. Swap names to use the other one.
#adjust midi defaults for required port.
#use run_file "path/to/this/file" to play

use_midi_logging false
use_debug false
define :ld do |dur|
ln=0
dur.each do |d|
ln+=d
end
return ln
end
define :pl do |nt,dur,ch=1,f=1|
  nt.zip(dur).each do |n,d|
    if n.respond_to?(:each)
      n.each do|nv|
      play nv,sustain: d
    end
    else
      play n,sustain: d
    end
  sleep d
  end
end

define :plx do |nt,dur,ch=1,f=1|
  nt.zip(dur).each do |n,d|
    if n.respond_to?(:each)
      n.each do|nv|
      midi nv,sustain: d*f,channel: ch
    end
    else
      midi n,sustain: d*f,channel: ch
    end
  sleep d
  end
end


use_synth :piano
use_midi_defaults port: "midi_through_port-0",vel_f: 0.9
midi_pc 0 
